/**
 * Slide-7 (`games/game-4` / `Weapon Hit 71 Senjata`) runtime for slide 1.
 *
 * SET 2..5 are not redrawn here. This file hosts slide 7's *own* code on slide
 * 1: `setSevenFire.ts` / `setSevenAnim.ts` are verbatim copies of slide 7's
 * `Game.ts` methods (generated by `scripts/gen-set-seven.py`), the shots are the
 * real slide-7 `Projectile` subclasses from `projectiles2..5.ts`, the stuck
 * rounds are slide 7's `drawStuckItem()`, and the sounds are slide 7's own
 * synthesizer. All of that was written against slide 7's game object; the shim
 * below is that object, forwarded to slide 1 through `SevenHooks`.
 *
 * Slide 1 keeps the physics and the rules: it moves the carrier round, decides
 * when the wheel is hit, and scores it. Slide 7 owns everything you see and
 * hear.
 */
import { Particles, type FX } from '../../../../games/game-4/src/game/particles';
import { newAnim, type StuckItem, type WeaponAnim, type WeaponId } from '../../../../games/game-4/src/game/weapons';
import type { Decal, Game } from '../../../../games/game-4/src/game/Game';
import { drawStuckItem } from '../../../../games/game-4/src/game/art';
import { FIRE_RECIPES } from './setSevenFire';
import type { SevenId } from './setSevenArt';
import type { Projectile } from '../../../../games/game-4/src/game/projectiles';

/** What slide 1 does for slide 7 (the parts slide 7 draws itself). */
export interface SevenHooks {
  /** Camera/wheel shake, in slide 7's units (0..20). */
  shake(amount: number): void;
  /** Brief slow motion after a heavy hit. */
  hitStop(seconds: number): void;
  /** Full-screen colour flash, rgb triple + strength. */
  flash(rgb: string, strength: number): void;
  /**
   * Paint into the wheel's own face canvas. The callback receives a context
   * centred on the wheel (slide 7's convention) and clipped to it.
   */
  paintWheel(draw: (c: CanvasRenderingContext2D) => void, radius: number): void;
  /** The wheel bounce + rim flash slide 7's `wheelImpact()` performs. */
  wheelImpact(power: number, color: string): void;
  /** Slide-1 wheel geometry, refreshed every frame. */
  wheel(): { x: number; y: number; R: number; angle: number };
}

/** Slide-7's wheel object, shared with the projectile classes. */
export interface SevenWheel {
  x: number;
  y: number;
  R: number;
  angle: number;
  bumpY: number;
  bumpV: number;
  flash: number;
  flashColor: string;
  scale: number;
  intro: number;
  shakeT: number;
  shakeX: number;
}

/**
 * The part of slide-7's `Game` the generated recipes and the projectile
 * classes touch. Slide 7's constructors take the real `Game` class, so the shim
 * is cast; this interface is what it actually provides.
 */
export interface SevenGame {
  particles: Particles;
  anim: WeaponAnim;
  wheel: SevenWheel;
  wheelGone: boolean;
  stuck: StuckItem[];
  time: number;
  addFX(f: FX): void;
  addWheelFX(f: FX): void;
  addDecal(d: Decal): void;
  paint(fn: (c: CanvasRenderingContext2D) => void): void;
  lens(x: number, y: number, r: number, s: number): void;
  shake(a: number): void;
  flashScreen(color: string, a: number): void;
  wheelImpact(power: number, color?: string): void;
  hitStop(t: number): void;
  after(delay: number, fn: () => void): void;
  pulseWheel(a: number): void;
  landed(it: StuckItem, clearDelay?: number): void;
  collide(p: Projectile, prev: number, tip: number): void;
}

/** Everything the generated slide-7 recipes expect from their host. */
export interface SevenHost {
  readonly g: Game;
  readonly particles: Particles;
  readonly anim: WeaponAnim;
  readonly orbTarget: { x: number; y: number };
  readonly gunX: number;
  readonly gunY: number;
  time: number;
  shotsFired: number;
  weaponId: WeaponId;
  readonly shots: Projectile[];
  addFX(f: FX): void;
  after(delay: number, fn: () => void): void;
  shake(a: number): void;
  flashScreen(color: string, a: number): void;
}

const NO_HOOKS: SevenHooks = {
  shake: () => {},
  hitStop: () => {},
  flash: () => {},
  paintWheel: () => {},
  wheelImpact: () => {},
  wheel: () => ({ x: 0, y: 0, R: 0, angle: 0 }),
};

/**
 * The bare `r,g,b` triple of a slide-7 colour, or `null` if it is not one.
 *
 * Slide-7 colour strings arrive in three shapes: a hex string, a finished CSS
 * colour (`'rgba(120,12,24,0.95)'`, which is what `PaintShot` hands over) and
 * the bare triplet the particle system uses (`'190,130,20'`). Anything that
 * needs to *wrap* a colour has to know which shape it got.
 */
function rgbOf(color: string | undefined): string | null {
  if (!color) return null;
  const c = color.trim();
  if (c[0] === '#') {
    let hex = c.slice(1);
    if (hex.length === 3) hex = hex.split('').map((ch) => ch + ch).join('');
    if (hex.length < 6 || !/^[0-9a-f]{6}/i.test(hex)) return null;
    const n = parseInt(hex.slice(0, 6), 16);
    return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
  }
  const fn = c.match(/^rgba?\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*(?:,\s*[\d.]+\s*)?\)$/i);
  if (fn) return `${+fn[1]},${+fn[2]},${+fn[3]}`;
  const triplet = c.match(/^(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})$/);
  if (triplet) return `${+triplet[1]},${+triplet[2]},${+triplet[3]}`;
  return null;
}

const FALLBACK_STAIN: readonly [string, string] = ['rgba(190,130,20,0.45)', 'rgba(120,70,10,0)'];

/**
 * Slide-7 decal colours, kept where slide 7 paints them.
 *
 * The `goo` stain (Paintball, and every SET‑7 liquid gun) used to be built by
 * wrapping `d.c[0]` in `rgba(…,0.45)` — but slide 7 hands `goo` *finished*
 * colours, so the stop became `rgba(rgba(120,12,24,0.95),0.45)`. `addColorStop`
 * throws a `SyntaxError` on that, inside `update()`, on the frame the paintball
 * lands: the update/render loop died mid-frame and the canvas was left with
 * half-drawn paint on it — the "efek paintball glitch" that also froze every
 * later effect on the same wheel.
 */
function decalPaint(d: Decal): [string, string] {
  switch (d.kind) {
    case 'poison':
      return ['rgba(120,220,90,0.42)', 'rgba(70,150,40,0)'];
    case 'smolder':
      return ['rgba(40,26,18,0.5)', 'rgba(20,12,8,0)'];
    case 'wet':
      return ['rgba(150,200,235,0.4)', 'rgba(90,140,190,0)'];
    default: {
      // `d.c` is [shadow, body, highlight]: the body shade becomes the stain.
      const rgb = rgbOf(d.c?.[1]) ?? rgbOf(d.c?.[0]) ?? rgbOf(d.c?.[2]);
      if (!rgb) return [...FALLBACK_STAIN] as [string, string];
      return [`rgba(${rgb},0.55)`, `rgba(${rgb},0)`];
    }
  }
}

export class SetSevenFx implements SevenHost {
  particles = new Particles();
  anim: WeaponAnim = newAnim();
  /** Slide-7 `after()` timers, in seconds. */
  timers: { t: number; fn: () => void }[] = [];
  /** Screen-space FX (muzzle flashes, lights, arcs, rings…). */
  fx: FX[] = [];
  /** Wheel-space FX (cracks glowing, rim spots): drawn from the wheel centre. */
  wheelFx: FX[] = [];
  /** Rounds slide 7's recipes created since the last `takeShots()`. */
  shots: Projectile[] = [];
  /** Rounds stuck in the wheel — slide 7's own `drawStuckItem()` art. */
  stuck: StuckItem[] = [];
  /**
   * Rounds slide 1 has already resolved and stopped carrying.
   *
   * Slide 7 never stops updating a round when it lands: the shotgun's pellet
   * shower, the minigun drum, the water jet and every `trail()` keep running
   * until the round leaves the screen. Slide 1 removes its carrier the frame
   * the round sticks, so those rounds are handed back here and live out their
   * own short life on slide 7's clock.
   */
  released: Projectile[] = [];
  /** The moving point slide-7's `pull` particles chase. */
  orbTarget = { x: 0, y: 0 };
  time = 0;
  shotsFired = 0;
  weaponId: WeaponId = 'snowball';
  wheelGone = false;
  gunX = 210;
  gunY = 575;

  private hooks: SevenHooks;

  /** Slide-7's wheel object, kept in sync with slide 1 every frame. */
  readonly wheel: SevenWheel = {
    x: 210, y: 0, R: 0, angle: 0, bumpY: 0, bumpV: 0, flash: 0,
    flashColor: 'rgba(255,255,255,', scale: 1, intro: 1, shakeT: 0, shakeX: 0,
  };

  /** The game shim handed to slide 7's projectile constructors. */
  readonly game: SevenGame;

  constructor(hooks: SevenHooks = NO_HOOKS) {
    this.hooks = hooks;
    const host = this;
    this.game = {
      particles: host.particles,
      get anim() { return host.anim; },
      wheel: host.wheel,
      get wheelGone() { return host.wheelGone; },
      get stuck() { return host.stuck; },
      get time() { return host.time; },
      addFX: (f) => host.addFX(f),
      addWheelFX: (f) => host.addWheel(f),
      addDecal: (d) => host.addDecal(d),
      paint: (fn) => host.hooks.paintWheel(fn, host.wheel.R),
      // Slide 1 has no refraction buffer; the lens flare is the only part of
      // slide 7's `lens()` a wheel game with no post-processing can show, and
      // those weapons already flash the screen there.
      lens: () => {},
      shake: (a) => host.hooks.shake(a),
      flashScreen: (color, a) => host.hooks.flash(color, a),
      wheelImpact: (power, color = 'rgba(255,255,255,') => host.hooks.wheelImpact(power, color),
      hitStop: (t) => host.hooks.hitStop(t),
      after: (delay, fn) => host.after(delay, fn),
      pulseWheel: () => {},
      landed: (it) => host.landed(it),
      // Slide 1 owns the flight path and the hit test (spikes, coins,
      // obstacles, boss health), so slide 7 must not resolve the shot itself.
      collide: () => {},
    };
  }

  /** Swap the hooks when slide 1 rebuilds its callbacks. */
  setHooks(hooks: SevenHooks) {
    this.hooks = hooks;
  }

  /** Slide 7's game object, typed for its own constructors. */
  get g(): Game {
    return this.game as unknown as Game;
  }

  addFX(f: FX) {
    this.fx.push(f);
    return f;
  }

  addWheel(f: FX) {
    this.wheelFx.push(f);
    return f;
  }

  shake(a: number) {
    this.hooks.shake(a);
  }

  flashScreen(color: string, a: number) {
    this.hooks.flash(color, a);
  }

  after(delay: number, fn: () => void) {
    this.timers.push({ t: delay, fn });
  }

  /**
   * Slide-7's `landed()`: the round is now part of the wheel. Slide 1 has
   * already scored the hit and stored its own collision entry, so this only
   * keeps the visible half of it — the stuck weapon art slide 7 draws.
   */
  landed(it: StuckItem) {
    it.world.x = this.wheel.x + Math.cos(it.angle + this.wheel.angle) * this.wheel.R;
    it.world.y = this.wheel.y + Math.sin(it.angle + this.wheel.angle) * this.wheel.R;
    this.stuck.push(it);
    this.stuck.sort((a, b) => b.protrude - a.protrude);
  }

  /** Slide-7's `addDecal()`: a stain baked into the wheel's face. */
  addDecal(d: Decal) {
    const R = this.wheel.R;
    if (R <= 0) return;
    const [inner, outer] = decalPaint(d);
    this.hooks.paintWheel((c) => {
      const lx = Math.cos(d.angle) * (R - 3);
      const ly = Math.sin(d.angle) * (R - 3);
      const g = c.createRadialGradient(lx, ly, 1, lx, ly, 16);
      try {
        g.addColorStop(0, inner);
        g.addColorStop(1, outer);
      } catch {
        // A colour a canvas refuses must never abort the frame: an unparsable
        // `addColorStop` throws, and this runs from inside `update()`.
        g.addColorStop(0, FALLBACK_STAIN[0]);
        g.addColorStop(1, FALLBACK_STAIN[1]);
      }
      c.fillStyle = g;
      c.beginPath();
      c.arc(lx, ly, 16, 0, Math.PI * 2);
      c.fill();
    }, R);
  }

  /** Refresh the wheel mirror from slide 1 before running slide-7 code. */
  syncWheel() {
    const w = this.hooks.wheel();
    this.wheel.x = w.x;
    this.wheel.y = w.y;
    this.wheel.R = w.R;
    this.wheel.angle = w.angle;
  }

  /** True while slide 7 still has something to draw or animate. */
  get busy(): boolean {
    return this.particles.list.length > 0 || this.fx.length > 0 || this.timers.length > 0
      || this.wheelFx.length > 0 || this.shots.some((p) => p.alive) || this.stuck.length > 0
      || this.released.length > 0;
  }

  /** Hand a round slide 1 just resolved back to slide 7's own clock. */
  release(shot: Projectile) {
    this.released.push(shot);
  }

  clear() {
    this.particles.clear();
    this.fx.length = 0;
    this.timers.length = 0;
    this.wheelFx.length = 0;
    this.shots.length = 0;
    this.stuck.length = 0;
    this.released.length = 0;
  }

  /** One frame of slide-7 time: its timers, particles and FX objects. */
  update(dt: number) {
    this.time += dt;
    for (let i = this.timers.length - 1; i >= 0; i--) {
      const t = this.timers[i];
      t.t -= dt;
      if (t.t <= 0) {
        this.timers.splice(i, 1);
        t.fn();
      }
    }
    this.particles.update(dt);
    for (const f of this.fx) f.update(dt);
    this.fx = this.fx.filter((f) => !f.done);
    for (const f of this.wheelFx) f.update(dt);
    this.wheelFx = this.wheelFx.filter((f) => !f.done);
    this.shots = this.shots.filter((p) => p.alive);
    // Rounds that outlived slide 1's carrier keep their own flight (and their
    // sub-projectiles) until they die, exactly like slide 7.
    for (const p of this.released) p.update(dt);
    this.released = this.released.filter((p) => p.alive);
    // Stuck rounds ride the wheel exactly like slide 7: their world position and
    // their "up" frame follow the rim as it turns and bounces.
    for (const it of this.stuck) {
      it.t += dt;
      const a = it.angle + this.wheel.angle;
      it.world.x = this.wheel.x + Math.cos(a) * this.wheel.R;
      it.world.y = this.wheel.y + Math.sin(a) * this.wheel.R;
      it.up = -a;
    }
  }

  /** Slide 7 draws its non-additive particles first… */
  draw(ctx: CanvasRenderingContext2D) {
    this.particles.draw(ctx, false);
  }

  /** …then the additive ones and every FX object on top. */
  drawFront(ctx: CanvasRenderingContext2D) {
    this.particles.draw(ctx, true);
    for (const f of this.fx) f.draw(ctx);
    for (const p of this.released) p.draw(ctx);
  }

  /** Wheel-space FX, drawn from the wheel centre like slide 7 does. */
  drawWheel(ctx: CanvasRenderingContext2D, cx: number, cy: number, radius: number, rot: number) {
    if (!this.wheelFx.length && !this.stuck.length) return;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(rot);
    for (const it of this.stuck) {
      ctx.save();
      ctx.rotate(it.angle);
      drawStuckItem(ctx, it, radius, this.time);
      ctx.restore();
    }
    for (const f of this.wheelFx) f.draw(ctx);
    ctx.restore();
  }

  /**
   * Take the shots a generated recipe just created. They keep the exact muzzle
   * position slide 7 gave them (`my - 6`, `my + 40` for the slingshot pouch,
   * `my - 38` for the blowpipe…), so nothing has to be re-derived here.
   */
  /**
   * The star pickup wipes the screen.
   *
   * Slide 1 drops every carrier it was flying, but a round it had already
   * resolved keeps flying on slide 7's own layer (`released`), so it has to go
   * too — otherwise the screen the star just cleared stays full of slide-7
   * rounds.
   */
  sweepCarried() {
    this.released.length = 0;
  }

  takeShots(): Projectile[] {
    const made = this.shots;
    this.shots = [];
    return made;
  }
}

/**
 * A still of the slide-7 round at `age` seconds after it left the muzzle, used
 * by the picker's effect card so \"Baru\" shows the real SET 2..5 projectile —
 * slide 7's own `draw()` for that weapon.
 */
export function drawSetSevenShotShell(
  c: CanvasRenderingContext2D,
  id: SevenId,
  age: number,
  travel = 0,
) {
  const fx = new SetSevenFx();
  fx.weaponId = id;
  fx.shotsFired = 1;
  FIRE_RECIPES[id](fx, 0, 0);
  // METEOR, MOONBEAM, STORM and friends release their round a fraction of a
  // second after the trigger, exactly like slide 7: run its timers first.
  for (let i = 0; i < 40 && !fx.shots.length; i++) fx.update(1 / 60);
  const shot = fx.shots[0];
  if (!shot) return;
  shot.x = 0;
  shot.y = -travel;
  shot.age = age;
  c.save();
  shot.draw(c);
  c.restore();
}
